function renderRooms(rooms) {
  listArea.innerHTML = '';

  var validRooms = [];
  var skipped = 0;
  rooms.forEach(function (r) {
    if (isRoomRecord(r)) validRooms.push(r);
    else skipped++;
  });

  if (!validRooms.length) {
    if (skipped > 0) {
      appendSkipNotice(skipped, true);
    } else {
      var pEmpty = document.createElement('p');
      pEmpty.className = 'empty';
      pEmpty.textContent = '还没有房间记录。';
      listArea.appendChild(pEmpty);
    }
    return;
  }

  // 跳过提示按本次完整返回内容统计：被关键词隐藏的房间仍是正常房间，
  // 绝不计为异常记录；提示始终先于表格或无匹配说明出现。
  if (skipped > 0) appendSkipNotice(skipped, false);

  // 非空关键词只对接口返回的名称字符串做连续文字匹配（区分英文大小写）：
  // 内部空格、中文、表情、尖括号与类似字符实体的文字都按原样参与匹配，
  // 不解释成网页内容或特殊表达式；编号、规则和其他列不参与匹配。
  // 名称缺失、为 null 或不是字符串（数字、对象等）的历史记录不参与
  // 非空关键词匹配；清空关键词后这些房间仍按原有方式成行，筛选不会
  // 删除或补写名称。命中行保持接口中的相对次序，逐行渲染方式不变。
  var keyword = trimName(filterInput.value);
  var matched = validRooms;
  if (keyword !== '') {
    matched = validRooms.filter(function (r) {
      return typeof r.name === 'string' && r.name.indexOf(keyword) !== -1;
    });
  }

  if (!matched.length) {
    // 列表里确实读到了房间对象，只是没有名称命中：明确告知无匹配，
    // 不能说成“还没有房间记录”。筛选输入框仍可直接修改或清空。
    var pNoMatch = document.createElement('p');
    pNoMatch.className = 'no-match';
    pNoMatch.textContent = '没有符合名称关键词的房间。';
    listArea.appendChild(pNoMatch);
    return;
  }

  var table = document.createElement('table');
  var thead = document.createElement('thead');
  var headRow = document.createElement('tr');
  ROOM_COLUMNS.forEach(function (col) {
    var th = document.createElement('th');
    th.textContent = col.label;
    headRow.appendChild(th);
  });
  thead.appendChild(headRow);
  table.appendChild(thead);
  var tbody = document.createElement('tbody');
  matched.forEach(function (r) {
    tbody.appendChild(buildRoomRow(r));
  });
  table.appendChild(tbody);
  listArea.appendChild(table);
}

// 最近一次成功读取的完整 rooms 数组；尚未成功读取或当前展示的是
// 加载失败提示时为 null。筛选只在内存中对这份完整数据进行，不重新
// 请求接口、不修改服务端任何记录。加载失败期间修改关键词不能把失败
// 提示换成空列表、无匹配结果或旧表格，因此那种情况下忽略输入变化。
var loadedRooms = null;
filterInput.addEventListener('input', function () {
  if (loadedRooms !== null) renderRooms(loadedRooms);
});

