// 请求接口、不修改服务端任何记录。加载失败期间修改关键词不能把失败
// 提示换成空列表、无匹配结果或旧表格，因此那种情况下忽略输入变化。
var loadedRooms = null;
filterInput.addEventListener('input', function () {
  if (loadedRooms !== null) renderRooms(loadedRooms);
});

// 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
// （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
// 防止旧数据覆盖新查询已展示的列表。
var listQuerySeq = 0;

function loadRooms() {
  var seq = ++listQuerySeq;
  return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
    .then(function (resp) {
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      return resp.json();
    })
    .then(function (data) {
      if (seq !== listQuerySeq) return;
      // 读取成功的唯一形态：顶层是 JSON 对象且 rooms 字段是数组。
      // 顶层为 null、数组或其他非对象值，缺少 rooms，或 rooms 为
      // null、对象、字符串等非数组值时，都按加载失败处理（走下面的
      // catch 显示失败提示），绝不能当成空列表显示“还没有房间记录”，
      // 也不能把其他内容猜成房间或保留旧表格冒充最新结果。
      if (data === null || typeof data !== 'object' || Array.isArray(data) ||
          !Array.isArray(data.rooms)) {
        throw new Error('房间列表响应格式异常');
      }
      // 记住本次完整返回，随后修改关键词只在内存中重新筛选这份数据；
      // renderRooms 内部会读取筛选框当前值，所以刷新落定后自动按最新
      // 关键词展示（等待刷新期间改过关键词也以最新输入为准）。

