  page.on('request', (req) => { if (req.method() === 'GET' && req.url().includes('/api/rooms')) getHits++; });

  await check('初始：10 个对象全部成行，跳过 2 条', async () => {
    const s = await listState(page);
    assert.equal(s.rows, 10);
    assert.match(s.skip, /有 2 条/);
    assert.deepEqual(await rowIds(page),
      ['r-alpha-up', 'r-alpha-low', 'r-evening', 'r-space', 'r-special',
        'r-null-name', 'r-missing-name', 'r-num-name', 'r-obj-name', '']);
  });

  await check('输入即筛选、区分英文大小写；不发 GET 请求', async () => {
    await setFilter(page, 'alpha');
    assert.deepEqual(await rowIds(page), ['r-alpha-low']);
    await setFilter(page, 'Alpha');
    assert.deepEqual(await rowIds(page), ['r-alpha-up']);
    await setFilter(page, 'ALPHA');
    assert.equal(await rowCount(page), 0);
    assert.equal(getHits, 0, '筛选不应触发接口请求');
  });

  await check('中文/表情/尖括号/实体样式文字按原样连续匹配', async () => {
    await setFilter(page, '晚间');
    assert.deepEqual(await rowIds(page), ['r-evening']);
    await setFilter(page, '😀');
    assert.deepEqual(await rowIds(page), ['r-special']);
    await setFilter(page, '<tag>');
    assert.deepEqual(await rowIds(page), ['r-special']);
    await setFilter(page, '&lt;');
    assert.deepEqual(await rowIds(page), ['r-special']);
    const cell = await page.$eval('#list-area table tbody tr td:nth-child(2)', (td) => td.textContent);
    assert.equal(cell, '<tag> &lt; 名称😀', '名称单元格仍按纯文本原样显示');
  });

  await check('内部空格保留：双空格命中，单空格不命中', async () => {
    await setFilter(page, 'a b  c');
    assert.deepEqual(await rowIds(page), ['r-space']);
    await setFilter(page, 'a b c');
    assert.equal(await rowCount(page), 0);
  });

  await check('首尾空白沿用名称整理规则；整理后为空等同未筛选', async () => {
    await setFilter(page, '   ');
    assert.equal(await rowCount(page), 10);
    await setFilter(page, ' 晚间 ');
    assert.deepEqual(await rowIds(page), ['r-evening']);
  });

  await check('无命中：显示固定文案，跳过提示仍按完整返回统计，非空列表提示', async () => {
    await setFilter(page, 'zzz不存在');
    const s = await listState(page);
    assert.equal(s.rows, 0);
    assert.equal(s.noMatch, '没有符合名称关键词的房间。');
    assert.equal(s.empty, false);
    assert.match(s.skip, /有 2 条/);
    assert.equal(s.filterDisabled, false, '仍可直接修改关键词');
  });

  await check('名称缺失/null/数字/对象不参与非空匹配，清空后原样成行且次序不变', async () => {
    await setFilter(page, 'r-null-name');
    assert.equal(await rowCount(page), 0, '编号不参与匹配');
    await setFilter(page, '五子棋');
    assert.deepEqual(await rowIds(page), ['r-evening'], '只有字符串名称参与匹配');
    await setFilter(page, '');
    assert.equal(await rowCount(page), 10);
    assert.deepEqual(await rowIds(page),
      ['r-alpha-up', 'r-alpha-low', 'r-evening', 'r-space', 'r-special',
        'r-null-name', 'r-missing-name', 'r-num-name', 'r-obj-name', '']);
    const s = await listState(page);
    assert.match(s.skip, /有 2 条/);
  });

  await check('筛选与创建表单互不影响', async () => {
    await page.type('#name', '表单里暂存的名称');
    await page.select('#game', 'ludo');
    await page.waitForFunction(() => document.getElementById('capacity').value === '2');
    await page.select('#capacity', '3');
    await page.type('#turnSeconds', '45');
    await setFilter(page, '晚间');
    assert.deepEqual(await rowIds(page), ['r-evening']);
    const form = await page.evaluate(() => ({
      name: document.getElementById('name').value,
      game: document.getElementById('game').value,
      cap: document.getElementById('capacity').value,
      t: document.getElementById('turnSeconds').value,
    }));
    assert.deepEqual(form, { name: '表单里暂存的名称', game: 'ludo', cap: '3', t: '45' });
    await setFilter(page, '');
  });

  const serverRooms = await (await fetch(baseURL + '/api/rooms')).json();
  assert.equal(serverRooms.rooms.length, 11, '服务端记录数不变');
  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

// ---------- 场景 2：保留关键词创建房间，刷新后按当前关键词筛选 ----------
{
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-filter-create-'));
  await seed(dataDir, [room('c1', '晚间五子棋')]);
  const { proc, ready } = startServer(dataDir);
  const baseURL = await ready;
  const page = await newPage(baseURL);
  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 1);
  await setFilter(page, '晚间');

  async function createRoom(name, game, cap, secs) {
    await page.$eval('#name', (el) => { el.value = ''; });
    await page.type('#name', name);
    await page.select('#game', game);
    await page.waitForFunction(() => !document.getElementById('capacity').disabled);
    await page.select('#capacity', String(cap));
    await page.$eval('#turnSeconds', (el) => { el.value = ''; });
    await page.type('#turnSeconds', String(secs));
    await page.click('#submit');
  }

  await check('关键词命中的新房间：成功提示与真实编号照常，刷新后出现', async () => {
    const created = new Promise((resolve) => page.on('response', (r) => {
      if (r.request().method() === 'POST' && r.url().includes('/api/rooms')) r.json().then(resolve);
    }));
    await createRoom('晚间飞行棋', 'ludo', 2, 30);
    const data = await created;
    await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 2);
    const msg = await page.$eval('#form-msg', (el) => el.textContent);
    assert.ok(msg.includes(data.id), '成功提示包含真实编号');
    assert.deepEqual(await rowIds(page), ['c1', data.id]);
    const s = await listState(page);
    assert.equal(s.filterValue, '晚间', '表单复位不清空关键词');
    assert.equal((await page.$('#name')).evaluate((el) => el.value), '', '创建表单仍正常复位');
  });

  await check('名称不命中的新房间：刷新后被关键词隐藏，清空后恢复；无自动多发请求', async () => {
    const created = new Promise((resolve) => page.on('response', (r) => {
      if (r.request().method() === 'POST' && r.url().includes('/api/rooms')) r.json().then(resolve);
    }));
    await createRoom('白日场', 'gomoku', 2, 0);
    const data = await created;
    await page.waitForFunction(() => document.getElementById('form-msg').textContent.includes(data.id));
    await new Promise((r) => setTimeout(r, 300));
    assert.deepEqual(await rowIds(page), ['c1'], '不命中新房间不出现在筛选后的列表');
    const all = await (await fetch(baseURL + '/api/rooms')).json();
    assert.equal(all.rooms.length, 3, '服务端确实保存了 3 条');
    await setFilter(page, '');
    assert.deepEqual(await rowIds(page), ['c1', undefined, undefined].slice(0, 0).length ? [] : await rowIds(page));
    const ids = await rowIds(page);
    assert.equal(ids.length, 3);
    assert.ok(ids.includes(data.id), '清空关键词后新房间恢复显示');
  });

  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

// ---------- 场景 3：真空列表 ----------
{
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-filter-empty-'));
  await seed(dataDir, []);
  const { proc, ready } = startServer(dataDir);
  const page = await newPage(await ready);
  await page.waitForSelector('#list-area .empty');
  await check('真正的空列表：输入/清空关键词都保持空列表提示，不出现无匹配文案', async () => {
    await setFilter(page, '任意关键词');
    let s = await listState(page);
    assert.equal(s.empty, true);
    assert.equal(s.noMatch, null);
    assert.equal(s.rows, 0);
    await setFilter(page, '');
    s = await listState(page);
    assert.equal(s.empty, true);
    assert.equal(s.noMatch, null);
  });
  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

// ---------- 场景 4：全部跳过 ----------
{
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-filter-allskip-'));
  await seed(dataDir, ['null', '42', '"字符串"']);
  const { proc, ready } = startServer(dataDir);
  const page = await newPage(await ready);
  await page.waitForSelector('#list-area .skip-notice');
  await check('全部跳过：输入/清空关键词都保持原有全部跳过说明', async () => {
    const before = await listState(page);
    assert.match(before.skip, /没有可展示的房间。本次返回的房间记录中有 3 条/);
    await setFilter(page, '字符串');
    const typing = await listState(page);
    assert.match(typing.skip, /没有可展示的房间。本次返回的房间记录中有 3 条/);
    assert.equal(typing.noMatch, null);
    assert.equal(typing.rows, 0);
    await setFilter(page, '');
    assert.match((await listState(page)).skip, /有 3 条|没有可展示的房间/);
  });
  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

// ---------- 场景 5：列表加载失败 ----------
{
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-filter-err-'));
  await writeFile(path.join(dataDir, 'rooms.json'), '截断的内容');
  const { proc, ready } = startServer(dataDir);
  const page = await newPage(await ready);
  await page.waitForSelector('#list-area .list-error');
  await check('加载失败：修改/清空关键词不能改成空列表、无匹配或旧表格', async () => {
    await setFilter(page, '晚间');
    let s = await listState(page);
    assert.ok(s.error);
    assert.equal(s.empty, false);
    assert.equal(s.noMatch, null);
    assert.equal(s.rows, 0);
    await setFilter(page, '');
    s = await listState(page);
    assert.ok(s.error);
    assert.equal(s.noMatch, null);
    assert.equal(s.empty, false);
  });
  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

// ---------- 场景 6：等待列表回应期间改关键词，以最新输入为准 ----------
{
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-filter-race-'));
  await seed(dataDir, [room('w1', '晚间五子棋'), room('w2', '白日飞行局')]);
  const { proc, ready } = startServer(dataDir);
  const baseURL = await ready;
  const page = await browser.newPage();
  const held = [];
  await page.setRequestInterception(true);
  page.on('request', (req) => {
    if (req.method() === 'GET' && req.url().includes('/api/rooms')) held.push(req);
    else req.continue();
  });
  await page.goto(baseURL, { waitUntil: 'load' });
  await page.waitForFunction(() => held.length > 0);
  await setFilter(page, '晚间');
  held[0].continue();
  await check('响应落定前改关键词：渲染以最新输入为准', async () => {
    await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 1);
    assert.deepEqual(await rowIds(page), ['w1']);
    await setFilter(page, '');
    await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 2);
  });
  proc.kill('SIGKILL');
  await rm(dataDir, { recursive: true, force: true });
  await page.close();
}

