import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import puppeteer from 'puppeteer-core';

const repoRoot = import.meta.dirname;
const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-dbg-'));
const serverBin = path.join(dir, 'score-arena');
await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-dbgdata-'));
await writeFile(path.join(dataDir, 'rooms.json'),
  '[\n{"id":"c1","name":"晚间五子棋","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"2026-01-01T00:00:00Z"}\n]\n');
const proc = spawn(serverBin, ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
  { stdio: ['ignore', 'pipe', 'inherit'] });
const baseURL = await new Promise((resolve, reject) => {
  let buf = '';
  proc.stdout.on('data', (c) => { buf += c; const m = buf.match(/listening on (http:\/\/\S+)/); if (m) resolve(m[1]); });
});
const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome', headless: true,
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });
const page = await browser.newPage();
page.on('request', (r) => { if (r.method() !== 'GET' || r.url().includes('api')) console.log('REQ', r.method(), r.url(), r.postData() || ''); });
page.on('response', async (r) => { if (r.url().includes('/api/rooms')) console.log('RESP', r.status(), (await r.text().catch(() => '<err>')).slice(0, 200)); });
await page.goto(baseURL, { waitUntil: 'load' });
await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 1);
await page.$eval('#room-filter', (el) => { el.value = '晚间'; el.dispatchEvent(new Event('input', { bubbles: true })); });

async function createRoom(name, game, cap, secs) {
  await page.$eval('#name', (el) => { el.value = ''; });
  await page.type('#name', name);
  await page.select('#game', game);
  await page.waitForFunction(() => !document.getElementById('capacity').disabled);
  await page.select('#capacity', String(cap));
  await page.$eval('#turnSeconds', (el) => { el.value = ''; });
  await page.type('#turnSeconds', String(secs));
  const p = page.waitForResponse((r) => r.request().method() === 'POST');
  await page.click('#submit');
  const resp = await p;
  return resp.status();
}

console.log('create1 status', await createRoom('晚间飞行棋', 'ludo', 2, 30));
await new Promise((r) => setTimeout(r, 500));
console.log('after1 msg:', await page.$eval('#form-msg', (e) => e.textContent));
console.log('after1 rows:', await page.$$eval('#list-area table tbody tr', (t) => t.length));
console.log('button disabled?', await page.$eval('#submit', (e) => e.disabled));
console.log('form:', await page.evaluate(() => ({
  name: document.getElementById('name').value,
  game: document.getElementById('game').value,
  cap: document.getElementById('capacity').value,
  t: document.getElementById('turnSeconds').value,
})));
console.log('create2 status', await createRoom('白日场', 'gomoku', 2, 0));
await new Promise((r) => setTimeout(r, 500));
console.log('after2 msg:', await page.$eval('#form-msg', (e) => e.textContent));
console.log('after2 rows:', await page.$$eval('#list-area table tbody tr', (t) => t.length));

await browser.close();
proc.kill('SIGKILL');
await rm(dir, { recursive: true, force: true });
await rm(dataDir, { recursive: true, force: true });

